controls.attributes:
type="text"
            id="title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="예: 보고서 초안 작성"
            className={commonInputClasses}
            required

type="number"
                    id="time"
                    value={estimatedTime}
                    min="0"
                    onChange={(e) => setEstimatedTime(Number(e.target.value))}
                    className={commonInputClasses}

value={note}
          onChange={(e) => onNoteChange(e.target.value)}
          placeholder="오늘 무엇이 잘 됐나요? 내일 개선할 점은?"
          className="w-full flex-grow bg-slate-700 border border-slate-600 rounded-md p-2.5 text-sm text-white placeholder-slate-400 focus:ring-indigo-500 focus:border-indigo-500 transition resize-none"

onClick={() => handleDeleteCategory(cat)}
                                disabled={isCategoryInUse(cat)}
                                className="text-slate-400 hover:text-red-500 disabled:text-slate-600 disabled:cursor-not-allowed transition"
                                title={isCategoryInUse(cat) ? "이 카테고리는 현재 사용 중이라 삭제할 수 없습니다." : "카테고리 삭제"}

type="text"
                        id="newCategory"
                        value={newCategory}
                        onChange={e => setNewCategory(e.target.value)}
                        placeholder="예: 운동"
                        className={commonInputClasses}

type="text"
            id="title"
            name="title"
            value={editedTask.title}
            onChange={handleChange}
            className={commonInputClasses}
            required

type="number"
                    id="estimatedTime"
                    name="estimatedTime"
                    value={editedTask.estimatedTime}
                    min="0"
                    onChange={handleChange}
                    className={commonInputClasses}

type="number"
            id="focus"
            min="1"
            value={durations[TimerMode.Focus]}
            onChange={(e) => handleChange(TimerMode.Focus, e.target.value)}
            className={commonInputClasses}

type="number"
            id="shortBreak"
            min="1"
            value={durations[TimerMode.ShortBreak]}
            onChange={(e) => handleChange(TimerMode.ShortBreak, e.target.value)}
            className={commonInputClasses}

type="number"
            id="longBreak"
            min="1"
            value={durations[TimerMode.LongBreak]}
            onChange={(e) => handleChange(TimerMode.LongBreak, e.target.value)}
            className={commonInputClasses}

key={tab}
              onClick={() => onFilterChange(tab)}
              className={`px-4 py-2 text-sm font-medium transition-colors whitespace-nowrap ${activeFilter === tab ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-slate-400 hover:text-white'}`}
